	VPSRLQ  $0x3f, Y6, Y8
	VPADDQ  Y6, Y6, Y6
	VPOR    Y6, Y8, Y6
	VPSRLQ  $0x3f, Y7, Y8
	VPADDQ  Y7, Y7, Y7
