	VPADDQ  Y5, Y0, Y0
	VPSHUFB -32(DX), Y14, Y14
	VPXOR   Y15, Y0, Y15
	VPADDQ  Y9, Y14, Y9
	VPADDQ  Y6, Y1, Y1
	VPXOR   Y4, Y9, Y4
	VPSHUFB -32(DX), Y15, Y15
	VPXOR   Y12, Y1, Y12
