	VPADDQ  Y10, Y15, Y10
	VPADDQ  -64(BX), Y1, Y1
	VPADDQ  Y7, Y2, Y2
	VPADDQ  Y4, Y3, Y3
	VPXOR   Y5, Y10, Y5
	VPSHUFB -32(DX), Y12, Y12
	VPXOR   Y13, Y2, Y13
	VPXOR   Y14, Y3, Y14
	VPSHUFB -64(DX), Y5, Y5
	VPADDQ  Y11, Y12, Y11
	VPADDQ  -96(SI), Y2, Y2
	VPSHUFB -96(DX), Y14, Y14
	VPADDQ  Y5, Y0, Y0
	VPXOR   Y6, Y11, Y6
	VPSHUFB -32(DX), Y13, Y13
	VPADDQ  Y9, Y14, Y9
	VPXOR   Y15, Y0, Y15
	VPSHUFB -64(DX), Y6, Y6
	VPADDQ  -32(SI), Y13, Y8
	VPSHUFB -96(DX), Y15, Y15
	VPADDQ  Y6, Y1, Y1
